#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * rule_key: host-graphify-priority
 * rule_id: 328d6670-51d3-4037-9ba4-7ce3a7d74b45
 * statement: 如果 graphify-out/GRAPH_REPORT.md 存在，回答架构或代码关系问题前必须先读它。遇到跨模块关系问题必须优先使用 graphify query/path/explain，而非全仓搜索。
 * trae_event: PreToolUse
 * matcher: Glob|Grep|SearchCodebase|Agent
 *
 * 场景发散设计结论：
 *
 * 1. 解构触发条件：
 *    - "架构或代码关系问题"包含：模块依赖、调用链、类继承、函数调用图、数据流向、路由逻辑、auth/billing 等核心模块关系
 *    - "跨模块关系问题"包含：涉及两个及以上模块路径的问题（如 "auth 如何调用 billing"）
 *    - "全仓搜索"包含：Glob/Grep/SearchCodebase/Agent 等需要遍历大量文件的工具
 *
 * 2. 场景分级：
 *    - critical（必须触发）：GRAPH_REPORT.md 存在 + prompt 含架构/跨模块关键词 + 工具是搜索类
 *    - skip（不触发）：GRAPH_REPORT.md 不存在；prompt 是纯单模块问题；工具不是搜索类；已经用过 graphify 命令
 *
 * 3. 边界情况：
 *    - GRAPH_REPORT.md 不存在 → skip（项目还没生成图谱）
 *    - prompt 无关键词 → skip（不是架构问题）
 *    - 已经用过 graphify → skip（用户已手动遵循规则）
 *
 * 4. shouldRun 设计：
 *    - 检查工具名是否匹配 SEARCH_TOOLS（Glob|Grep|SearchCodebase|Agent）
 *    - 检查 cwd 下 graphify-out/GRAPH_REPORT.md 是否存在
 *    - 检查 userPrompt 是否含架构关键词
 *    - 检查 command_history 是否已用过 graphify（避免重复拦截）
 *
 * 5. run 检查逻辑：
 *    - 如果满足条件，REJECT 并给出 graphify 命令建议
 */

import fs from "fs";
import path from "path";
import { runHook, getCwd } from "./_lib.mjs";

// 架构/跨模块关键词
const ARCH_KEYWORDS = [
  "架构", "architecture", "依赖", "dependency", "调用", "call", "继承", "inherit",
  "模块", "module", "关系", "relation", "流向", "flow", "路由", "route",
  "如何", "how", "在哪", "where", "谁调", "who call", "跨模块", "cross-module",
  "auth", "billing", "gateway", "核心", "core", "结构", "structure",
  "GRAPH_REPORT", "graphify"
];

// 搜索类工具
const SEARCH_TOOLS = /^(Glob|Grep|SearchCodebase|Agent)$/i;

// 判断是否应该触发
function shouldRun(context) {
  const toolName = context.tool?.name ?? "";
  const prompt = context.userPrompt ?? "";
  const cwd = getCwd(context);

  // 1. 工具必须是搜索类
  if (!SEARCH_TOOLS.test(toolName)) return false;

  // 2. GRAPH_REPORT.md 必须存在
  const graphReportPath = path.join(cwd, "graphify-out", "GRAPH_REPORT.md");
  if (!fs.existsSync(graphReportPath)) return false;

  // 3. prompt 必须含架构关键词
  const hasKeyword = ARCH_KEYWORDS.some(kw => prompt.toLowerCase().includes(kw.toLowerCase()));
  if (!hasKeyword) return false;

  // 4. 已经用过 graphify 则不拦截（检查 command_history）
  const history = context.command_history ?? [];
  const usedGraphify = history.some(cmd => /graphify\s+(query|path|explain|update)/i.test(cmd));
  if (usedGraphify) return false;

  return true;
}

// 执行检查
function run(context) {
  const prompt = context.userPrompt ?? "";
  const cwd = getCwd(context);

  // 提取关键词用于生成建议
  const keywords = ARCH_KEYWORDS.filter(kw => prompt.toLowerCase().includes(kw.toLowerCase()));
  const suggestedQuery = keywords.length > 0 ? `"${keywords[0]}"` : "\"architecture\"";

  return {
    action: "REJECT",
    reason: `架构/跨模块关系问题必须先走 Graphify。graphify-out/GRAPH_REPORT.md 已存在，请在全仓搜索前先读取它。`,
    suggestions: [
      `graphify query ${suggestedQuery}`,
      `graphify path "<模块A>" "<模块B>"`,
      `graphify explain "<概念>"`,
      `cat graphify-out/GRAPH_REPORT.md`,
      "如果图谱不完整，先运行 npm run graph:rebuild"
    ]
  };
}

// 主流程入口
runHook(shouldRun, run, "PreToolUse");